drop function public.public_snapshot();
create function public.public_snapshot(before_cursor text default null)returns jsonb language sql stable security invoker set search_path=''as $$select jsonb_build_object('profiles',(select coalesce(jsonb_agg(x),'[]')from(select * from public.profiles limit 50)x),'posts',(select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('reaction_count',(select count(*)from public.reactions where post_id=x.id),'reply_count',(select count(*)from public.comments where post_id=x.id))),'[]')from(select * from public.posts where before_cursor is null or(created_at,id)<(split_part(before_cursor,'|',1)::timestamptz,split_part(before_cursor,'|',2)::uuid)order by created_at desc,id desc limit 30)x),'projects',(select coalesce(jsonb_agg(x),'[]')from(select * from public.projects limit 30)x),'comments','[]'::jsonb,'project_members','[]'::jsonb,'papers','[]'::jsonb,'collaborations','[]'::jsonb,'applications','[]'::jsonb,'notifications','[]'::jsonb,'reports','[]'::jsonb,'contributions','[]'::jsonb,'audit','[]'::jsonb,'preferences','[]'::jsonb,'reactions','[]'::jsonb,'bookmarks','[]'::jsonb,'follows','[]'::jsonb,'blocks','[]'::jsonb,'helpful','[]'::jsonb,'roles','[]'::jsonb)$$;
revoke all on function public.public_snapshot(text)from public;grant execute on function public.public_snapshot(text)to anon,authenticated;
